constexpr uint64_t StringToUint64WithBase(std::string_view str, uint8_t base) {
  uint64_t result = 0;

  for (const char digit : str) {
    int value = -1;

    if (digit >= '0' && digit <= '9') {
      value = digit - '0';
    } else if (digit >= 'A' && digit <= 'Z') {
      value = digit - 'A' + 10;
    } else if (digit >= 'a' && digit <= 'z') {
      value = digit - 'a' + 10;
    }

    if (value < 0 || value >= base) {
      break;
    }

    result = result * base + static_cast<uint64_t>(value);
  }

  return result;
}
