struct ContiguousMemoryRange {
  uint8_t* begin;
  uint8_t* end;

  inline bool is_valid() const { return begin != nullptr; }
  inline void reset() { begin = nullptr; }
  inline size_t size() const { return static_cast<size_t>(end - begin); }
};

